from taf.ul.kpi_selector.operations.factory_prototype.classical_factory_prototype import OperationFactoryPrototype
from taf.ul.kpi_selector.operations.cell_unblock.classical_cell_unblock.cell_unblock_prototype import CellUnblock


class CellUnblockFactory(OperationFactoryPrototype):
    def __init__(self):
        super(CellUnblockFactory, self).__init__()

    def get_kpi(self, cell_dist_name=""):
        """
        Gets kpi for cell unblock operation.
        :param cell_dist_name: dist_name of the cell, which KPI cell block timeout will be applied to
        :type cell_dist_name: str
        :return: dictionary with timeout, requirement and operation description for cell unblock
        :rtype: dict
        """
        return CellUnblock(self.bts).get_kpi(cell_dist_name=cell_dist_name)
